rules.fix_code:
h1 { font-size: clamp(2rem, 6.4vw + 0.4rem, 3.5rem);
     line-height: 1.04; letter-spacing: -.02em;
     max-width: 18ch; text-wrap: balance; }

@font-face {
  font-family: "Face Fallback"; src: local("Arial");
  ascent-override: 89.26%; descent-override: 19.61%;
  line-gap-override: 0%; size-adjust: 102.08%;
}
/* THESE NUMBERS ARE AN EXAMPLE. Compute your own. */

::selection { background: var(--accent); color: var(--paper); }
:root { accent-color: var(--accent); }
a { text-underline-offset: 3px; }
